const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '5份' },
      { kind: 'text', payload: '2份' },
      { kind: 'text', payload: '撬棒' },
      { kind: 'text', payload: '石头' },
      { kind: 'text', payload: '动力臂 : 阻力臂 = 5 : 2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var groundY = H * 0.86;
    var F = { x: W * 0.38, y: H * 0.68 };
    var P = { x: W * 0.18, y: H * 0.62 };
    var E = { x: W * 0.88, y: H * 0.83 };
    var slope = (E.y - F.y) / (E.x - F.x);
    function ln(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    function poly(points, close) {
      var cmds = [['M', points[0][0], points[0][1]]];
      for (var i = 1; i < points.length; i++) {
        cmds.push(['L', points[i][0], points[i][1]]);
      }
      if (close) { cmds.push(['Z']); }
      return cmds;
    }
    var yDim = H * 0.92;
    var tickLen = H * 0.012;
    var extTop = groundY - H * 0.02;
    var ticks = [];
    var xs = [P.x, F.x, E.x];
    for (var j = 0; j < xs.length; j++) {
      ticks.push(['M', xs[j], yDim - tickLen]);
      ticks.push(['L', xs[j], yDim + tickLen]);
      ticks.push(['M', xs[j], extTop]);
      ticks.push(['L', xs[j], yDim]);
    }
    var leverYAt = function (x) {
      return F.y + (x - F.x) * slope;
    };
    var Pext = { x: W * 0.13, y: 0 };
    Pext.y = leverYAt(Pext.x);
    var leverLabelX = W * 0.64;
    var leverLabelY = leverYAt(leverLabelX) - H * 0.035;
    var stoneCenterX = W * 0.12;
    var effortArrowX = E.x;
    var effortArrowTop = E.y - H * 0.12;
    var head = W * 0.015;
    var effortArrowCmds = [
      ['M', effortArrowX, effortArrowTop],
      ['L', effortArrowX, E.y],
      ['M', effortArrowX - head, E.y - head],
      ['L', effortArrowX, E.y],
      ['L', effortArrowX + head, E.y - head]
    ];
    var stonePoints = [
      [W * 0.05, groundY],
      [W * 0.07, H * 0.60],
      [W * 0.12, H * 0.54],
      [W * 0.175, H * 0.58],
      [P.x, P.y],
      [P.x, groundY]
    ];
    var fulcrumPoints = [
      [F.x, F.y],
      [F.x - W * 0.045, groundY],
      [F.x + W * 0.045, groundY]
    ];
    return {
      schemaVersion: 1,
      sceneId: 'lever-scene',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'bg', commands: poly([[0, 0], [W, 0], [W, H], [0, H]], true) },
        { id: 'ground', commands: ln(W * 0.03, groundY, W * 0.97, groundY) },
        { id: 'stone', commands: poly(stonePoints, true) },
        { id: 'fulcrum', commands: poly(fulcrumPoints, true) },
        { id: 'lever', commands: ln(Pext.x, Pext.y, E.x, E.y) },
        { id: 'effortArrow', commands: effortArrowCmds },
        { id: 'resDim', commands: ln(P.x, yDim, F.x, yDim) },
        { id: 'powDim', commands: ln(F.x, yDim, E.x, yDim) },
        { id: 'ticks', commands: ticks },
        { id: 'fulcrumLeader', commands: ln(F.x, F.y - H * 0.045, F.x, F.y) }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'bg', fill: '#FFFDF5' },
        { type: 'path', pathId: 'ground', fill: '#6B7280', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 'fulcrum', fill: '#4A4E69', stroke: { width: 2, join: 'round' } },
        { type: 'path', pathId: 'lever', fill: '#9A6B3F', stroke: { width: 12, cap: 'round' } },
        { type: 'path', pathId: 'stone', fill: '#8D99AE', stroke: { width: 3, join: 'round' } },
        { type: 'path', pathId: 'effortArrow', fill: '#C1121F', stroke: { width: 4, cap: 'round', join: 'round' } },
        { type: 'path', pathId: 'resDim', fill: '#6C757D', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'powDim', fill: '#6C757D', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'ticks', fill: '#6C757D', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'fulcrumLeader', fill: '#B23A48', stroke: { width: 1.5, cap: 'round' } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: F.x, y: F.y - H * 0.05 }, hAlign: 'center', vAlign: 'bottom', color: '#B23A48' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: (F.x + E.x) / 2, y: yDim - H * 0.025 }, hAlign: 'center', vAlign: 'bottom', color: '#1D3557' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: (P.x + F.x) / 2, y: yDim - H * 0.025 }, hAlign: 'center', vAlign: 'bottom', color: '#1D3557' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: (F.x + E.x) / 2, y: yDim + H * 0.025 }, hAlign: 'center', vAlign: 'top', color: '#1D3557' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: (P.x + F.x) / 2, y: yDim + H * 0.025 }, hAlign: 'center', vAlign: 'top', color: '#1D3557' },
        { type: 'label', contentId: metrics[5].contentId, anchor: { x: leverLabelX, y: leverLabelY }, hAlign: 'center', vAlign: 'bottom', color: '#7C4A2D' },
        { type: 'label', contentId: metrics[6].contentId, anchor: { x: stoneCenterX, y: H * 0.51 }, hAlign: 'center', vAlign: 'bottom', color: '#4A5568' },
        { type: 'label', contentId: metrics[7].contentId, anchor: { x: W * 0.06, y: H * 0.09 }, hAlign: 'left', vAlign: 'middle', color: '#1D3557' }
      ] }
    };
  }
};
